3884	DynamicPrintConfig PresetBundle::full_fff_config(bool apply_extruder, std::optional<std::vector<int>> filament_maps_new) const
3885	{
3886	    DynamicPrintConfig out;
3887	    out.apply(FullPrintConfig::defaults());
3888	    out.apply(this->prints.get_edited_preset().config);
3889	    // Add the default filament preset to have the "filament_preset_id" defined.
3890		out.apply(this->filaments.default_preset().config);
3891		out.apply(this->printers.get_edited_preset().config);
