3893	
3894	    // BBS
3895	    size_t  num_filaments = this->filament_presets.size();
3896	
3897	    std::vector<int> filament_maps = out.option<ConfigOptionInts>("filament_map")->values;
3898	    if (filament_maps_new.has_value())
3899	        filament_maps = *filament_maps_new;
3900	    //in some middle state, they may be different
3901	    if (filament_maps.size() != num_filaments) {
3902	        filament_maps.resize(num_filaments, 1);
3903	    }
3904	    else {
3905	        assert(filament_maps.size() == num_filaments);
3906	    }
3907	
3908	    auto* extruder_diameter = dynamic_cast<const ConfigOptionFloats*>(out.option("nozzle_diameter"));
3909	    // Collect the "compatible_printers_condition" and "inherits" values over all presets (print, filaments, printers) into a single vector.
3910	    std::vector<std::string> compatible_printers_condition;
3911	    std::vector<std::string> compatible_prints_condition;
3912	    std::vector<std::string> inherits;
3913	    std::vector<std::string> filament_ids;
3914	    std::vector<std::string> print_compatible_printers;
3915	    //BBS: add logic for settings check between different system presets
3916	    std::vector<std::string> different_settings;
3917	    std::string different_print_settings, different_printer_settings;
3918	    compatible_printers_condition.emplace_back(this->prints.get_edited_preset().compatible_printers_condition());
3919	
3920	    const ConfigOptionStrings* compatible_printers =  (const_cast<PresetBundle*>(this))->prints.get_edited_preset().config.option<ConfigOptionStrings>("compatible_printers", false);
3921	    if (compatible_printers)
3922	        print_compatible_printers = compatible_printers->values;
3923	    //BBS: add logic for settings check between different system presets
3924	    std::string print_inherits = this->prints.get_edited_preset().inherits();
3925	    inherits                     .emplace_back(print_inherits);
3926	    const Preset* print_parent_preset =  this->prints.get_selected_preset_parent();
3927	    if (print_parent_preset) {
3928	        std::vector<std::string> dirty_options = this->prints.dirty_options_without_option_list(&(this->prints.get_edited_preset()), print_parent_preset, ignore_settings_list, false);
3929	        if (!dirty_options.empty()) {
3930	            different_print_settings = Slic3r::escape_strings_cstyle(dirty_options);
3931	        }
3932	    }
3933	    different_settings.emplace_back(different_print_settings);
3934	
3935	    //BBS: update printer config related with variants
3936	    if (apply_extruder) {
3937	        out.update_values_to_printer_extruders(out, printer_options_with_variant_1, "printer_extruder_id", "printer_extruder_variant");
3938	        out.update_values_to_printer_extruders(out, printer_options_with_variant_2, "printer_extruder_id", "printer_extruder_variant", 2);
3939	        //update print config related with variants
3940	        out.update_values_to_printer_extruders(out, print_options_with_variant, "print_extruder_id", "print_extruder_variant");
3941	    }
3942	
3943	    if (num_filaments <= 1) {
3944	        //BBS: update filament config related with variants
3945	        DynamicPrintConfig filament_config = this->filaments.get_edited_preset().config;
3946	        if (apply_extruder)
3947	            filament_config.update_values_to_printer_extruders(out, filament_options_with_variant, "", "filament_extruder_variant", 1, filament_maps[0]);
3948	        out.apply(filament_config);
3949	        compatible_printers_condition.emplace_back(this->filaments.get_edited_preset().compatible_printers_condition());
3950	        compatible_prints_condition  .emplace_back(this->filaments.get_edited_preset().compatible_prints_condition());
3951	        //BBS: add logic for settings check between different system presets
