3962	            std::vector<std::string> dirty_options = this->filaments.dirty_options_without_option_list(&(this->filaments.get_edited_preset()), filament_parent_preset, ignore_settings_list, false);
3963	            if (!dirty_options.empty()) {
3964	                different_filament_settings = Slic3r::escape_strings_cstyle(dirty_options);
