2488	    const DynamicPrintConfig    &combined_config,
2489	    //different settings list
2490	    const std::set<std::string> &different_settings_list,
2491	    // Select the preset after loading?
2492	    LoadAndSelect                select,
2493	    const Semver                file_version,
2494	    const std::string           filament_id)
2495	{
2496	    // Load the preset over a default preset, so that the missing fields are filled in from the default preset.
2497	    DynamicPrintConfig cfg(this->default_preset_for(combined_config).config);
2498	    // SoftFever: ignore print connection info from project
