2512	    if (! found) {
2513	        // Try to match the original_name against the "renamed_from" profile names of loaded system profiles.
2514	        it = this->find_preset_renamed(original_name);
2515	        found = it != m_presets.end();
2516	    }
2517	
2518	    std::string extruder_id_name, extruder_variant_name;
2519	    std::set<std::string> *key_set1 = nullptr, *key_set2 = nullptr;
2520	    Preset::get_extruder_names_and_keysets(m_type, extruder_id_name, extruder_variant_name, &key_set1, &key_set2);
2521	
2522	    if (!inherits.empty() && (different_settings_list.size() > 0)) {
2523	        auto iter = this->find_preset_internal(inherits);
2524	        if (iter == m_presets.end() || iter->name != inherits)
2525	            iter = this->find_preset_renamed(inherits);
2526	        if (iter != m_presets.end()) {
2527	            //std::vector<std::string> dirty_options = cfg.diff(iter->config);
2528	            BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << boost::format(": change preset %1% inherit %2% 's value to %3% 's values")%original_name %inherits %path;
2529	            cfg.update_non_diff_values_to_base_config(iter->config, keys, different_settings_list, extruder_id_name, extruder_variant_name, *key_set1, *key_set2);
2530	        }
2531	    }
2532	    else if (found && it->is_system && (different_settings_list.size() > 0)) {
2533	        BOOST_LOG_TRIVIAL(info) << __FUNCTION__ << boost::format(": change preset %1% 's value to %2% 's values")%original_name %path;
2534	        cfg.update_non_diff_values_to_base_config(it->config, keys, different_settings_list, extruder_id_name, extruder_variant_name, *key_set1, *key_set2);
2535	    }
2536	
2537	    //BBS: add config related logs
2538	    BOOST_LOG_TRIVIAL(debug) << __FUNCTION__ << boost::format(" enter, type %1% , path %2%, name %3%, original_name %4%, inherits %5%")%Preset::get_type_string(m_type) %path %name %original_name %inherits;

