2461	static bool profile_print_params_same(const DynamicPrintConfig &cfg_old, const DynamicPrintConfig &cfg_new)
2462	{
2463	    t_config_option_keys diff = cfg_old.diff(cfg_new);
2464	    // Following keys are used by the UI, not by the slicing core, therefore they are not important
