465	    // Set a single vector item from a range of another vector option
466	    // This function is useful to split values from multiple extrder / filament settings into separate configurations.
467	    void set(const ConfigOption* rhs, size_t start, size_t len) override
468	    {
469	        // It is expected that the vector value has at least one value, which is the default, if not overwritten.
470	        assert(!this->values.empty());
471	        T v = this->values.front();
472	        this->values.resize(len, v);
473	        if (rhs->type() == this->type()) {
474	            // Assign the first value of the rhs vector.
475	            auto other = static_cast<const ConfigOptionVector<T>*>(rhs);
476	            if (other->values.size() < (start+len))
477	                throw ConfigurationError("ConfigOptionVector::set_with(): Assigning from an vector with invalid size");
478	            for (size_t i = 0; i < len; i++)
479	                this->values[i] = other->get_at(start+i);
480	        }
481	        else
482	            throw ConfigurationError("ConfigOptionVector::set_with(): Assigning an incompatible type");
483	    }
