487	    //keep_index: which index in this vector need to be restored
488	    virtual void set_with_restore(const ConfigOptionVectorBase* rhs, std::vector<int>& restore_index, int stride) override
489	    {
490	        if (rhs->type() == this->type()) {
491	            //backup original ones
492	            std::vector<T> backup_values = this->values;
493	            // Assign the first value of the rhs vector.
494	            auto other = static_cast<const ConfigOptionVector<T>*>(rhs);
495	            this->values = other->values;
496	
497	            if (other->values.size() != (restore_index.size()*stride))
498	                throw ConfigurationError("ConfigOptionVector::set_with_restore(): Assigning from an vector with invalid restore_index size");
499	
500	            for (size_t i = 0; i < restore_index.size(); i++) {
501	                if (restore_index[i] != -1) {
502	                    for (size_t j = 0; j < stride; j++)
503	                        this->values[i * stride +j] = backup_values[restore_index[i] * stride +j];
504	                }
505	            }
506	        }
507	        else
508	            throw ConfigurationError("ConfigOptionVector::set_with_restore(): Assigning an incompatible type");
509	    }
