766	bool ProjectAutosave::open_managed_project(const std::string& project_id)
767	{
768	    if (!save_now())
769	        return false;
770	    ensure_current_preview();
771	    if (m_store->project_id() == project_id)
772	        return true;
773	    const std::string previous_id = m_store->head_id();
774	    std::optional<ProjectVersionStore::Materialization> target_materialized;
775	    std::unique_ptr<ProjectVersionStore> target;
776	    bool replacement_started = false;
777	    const auto load = [this](const ProjectVersionStore::Materialization& materialized,
778	                             const ProjectVersionStore::Version& version) {
779	        m_plater.reset();
780	        m_plater.take_snapshot("Open local project", UndoRedo::SnapshotType::ProjectSeparator);
781	        auto strategy = LoadStrategy::Restore;
782	        if (materialized.empty)
783	            strategy = strategy | LoadStrategy::AllowEmpty;
784	        const auto loaded = m_plater.load_files(
785	            std::vector<boost::filesystem::path>{boost_path(materialized.metadata),
786	                                                 boost_path(materialized.absent_original)},
787	            strategy, false);
788	        if ((loaded.empty() && !materialized.empty) || (materialized.empty && !m_plater.model().objects.empty()))
789	            throw std::runtime_error("local project could not be restored");
790	        m_plater.set_project_filename(wxString::FromUTF8(version.source_path));
791	    };
792	    try {
793	        target = std::make_unique<ProjectVersionStore>(m_root, project_id);
794	        const auto versions = target->history();
795	        if (versions.empty() || versions.back().id != target->head_id())
796	            throw std::runtime_error("local project has no current version");
797	        target_materialized = target->materialize(target->head_id());
798	        replacement_started = true;
799	        load(*target_materialized, versions.back());
800	        m_persistence.adopt_managed_state(target_materialized->semantic_state);
801	        target->seed_from_live(m_plater.model());
802	        m_last_capture_input = observed_input();
803	        m_seen_model_input = m_last_capture_input;
804	        m_committed_semantic_revision = m_persistence.document().doc_revision();
805	        m_seen_semantic_revision = m_committed_semantic_revision;
806	        m_first_semantic_edit.reset();
807	        if (m_active_materialization && m_active_materialization_project == m_store->project_id()) {
808	            try {
809	                m_store->remove_materialization(*m_active_materialization);
810	            } catch (const std::exception& cleanup_error) {
811	                m_warning = std::string("Old project workspace could not be removed: ") + cleanup_error.what();
812	                BOOST_LOG_TRIVIAL(warning) << m_warning;
813	            }
