803	        m_seen_model_input = m_last_capture_input;
804	        m_committed_semantic_revision = m_persistence.document().doc_revision();
805	        m_seen_semantic_revision = m_committed_semantic_revision;
806	        m_first_semantic_edit.reset();
807	        if (m_active_materialization && m_active_materialization_project == m_store->project_id()) {
808	            try {
809	                m_store->remove_materialization(*m_active_materialization);
810	            } catch (const std::exception& cleanup_error) {
811	                m_warning = std::string("Old project workspace could not be removed: ") + cleanup_error.what();
812	                BOOST_LOG_TRIVIAL(warning) << m_warning;
813	            }
814	        }
815	        m_store = std::move(target);
816	        m_project_name = versions.back().project_name;
817	        m_active_materialization = *target_materialized;
818	        m_active_materialization_project = project_id;
819	        m_committed_head = m_store->head_id();
820	        m_revision = 0;
821	        for (const auto& version : versions)
822	            m_revision = std::max(m_revision, version.revision);
823	        m_error.clear();
824	        m_state = State::Saved;
825	        m_resume_attempted = true;
826	        m_next_probe = Clock::now() + kProbeInterval;
827	        return true;
828	    } catch (const std::exception& error) {
829	        const std::string reason = error.what();
830	        if (replacement_started) {
831	            try {
832	                const auto previous = m_store->materialize(previous_id);
833	                const auto versions = m_store->history();
834	                const auto old = std::find_if(versions.begin(), versions.end(), [&previous_id](const auto& version) {
835	                    return version.id == previous_id;
836	                });
837	                if (old == versions.end())
838	                    throw std::runtime_error("previous project version was not found");
839	                load(previous, *old);
840	                m_persistence.adopt_managed_state(previous.semantic_state);
841	                m_store->seed_from_live(m_plater.model());
842	                m_active_materialization = previous;
843	                m_active_materialization_project = m_store->project_id();
844	                if (target && target_materialized)
845	                    target->remove_materialization(*target_materialized);
846	            } catch (const std::exception& rollback_error) {
847	                fail(reason + "; previous project also failed to reload: " + rollback_error.what());
848	                return false;
849	            }
850	        }
851	        fail(reason);
852	        return false;
853	    }
854	}
