   715	        if (!entry.is_directory() || !std::filesystem::is_regular_file(entry.path() / "HEAD"))
   716	            continue;
   717	        try {
   718	            std::ifstream head_file(entry.path() / "HEAD", std::ios::binary);
   719	            const std::string head((std::istreambuf_iterator<char>(head_file)), std::istreambuf_iterator<char>());
   720	            if (head.empty()) continue;
   721	            std::vector<std::string> versions;
   722	            if (head.front() == '{')
   723	                versions = nlohmann::json::parse(head).at("versions").get<std::vector<std::string>>();
   724	            else {
   725	                std::string version = head;
   726	                if (!version.empty() && version.back() == '\n') version.pop_back();
   727	                versions.push_back(std::move(version));
   728	            }
   729	            for (auto it = versions.rbegin(); it != versions.rend(); ++it) {
   730	                if (it->empty() || it->find_first_of("/\\") != std::string::npos) continue;
   731	                std::ifstream manifest_file(entry.path() / "versions" / *it / "manifest.json", std::ios::binary);
   732	                if (!manifest_file) continue;
   733	                const nlohmann::json manifest = nlohmann::json::parse(manifest_file);
   734	                if (same_source_path(source, std::filesystem::u8path(manifest.value("sourcePath", std::string())))) {
   735	                    auto updated = std::filesystem::last_write_time(entry.path() / "HEAD");
   736	                    if (std::filesystem::is_regular_file(entry.path() / "current-state.json"))
   737	                        updated = std::max(updated, std::filesystem::last_write_time(entry.path() / "current-state.json"));
   738	                    matches.emplace_back(updated, entry.path().filename().string());
   739	                    break;
   740	                }
   741	            }
   742	        } catch (const std::exception& error) {
   743	            BOOST_LOG_TRIVIAL(warning) << "Local project source index unavailable: " << entry.path().string()
   744	                                       << ": " << error.what();
   745	        }
   746	    }
   747	    std::sort(matches.begin(), matches.end(), [](const auto& a, const auto& b) {
   748	        return a.first != b.first ? a.first > b.first : a.second > b.second;
   749	    });
   750	    std::vector<std::string> result;
   751	    result.reserve(matches.size());
   752	    for (const auto& [updated, id] : matches)
   753	        result.push_back(id);
   754	    const wxString current_source = m_plater.get_project_filename(".3mf");
   755	    if (same_source_path(source, std::filesystem::u8path(current_source.ToUTF8().data()))) {
   756	        const std::string& current_id = m_persistence.document().project_id();
   757	        const auto current = std::find(result.begin(), result.end(), current_id);
   758	        if (current != result.end())
   759	            std::rotate(result.begin(), current, current + 1);
   760	        else if (!current_id.empty())
   761	            result.insert(result.begin(), current_id);
   762	    }
   763	    return result;
   764	}
