   856	void ProjectAutosave::ensure_current_preview()
   857	{
   858	    if (!m_store || m_store->head_id().empty() || m_plater.model().objects.empty())
   859	        return;
   860	    try {
   861	        const auto project = m_root / m_store->project_id();
   862	        if (!saved_preview(project, m_store->head_id()).empty())
   863	            return;
   864	        GLCanvas3D* canvas = m_plater.get_view3D_canvas3D();
   865	        if (canvas == nullptr || !canvas->is_initialized() || m_plater.get_partplate_list().get_plate_count() == 0)
   866	            return;
   867	        ThumbnailData data;
   868	        // Frame all model volumes, including objects on other plates.
   869	        ThumbnailsParams params{{}, false, true, false, true, 0, false};
   870	        canvas->render_thumbnail(data, 256, 256, params, Camera::EType::Ortho);
   871	        if (!data.is_valid())
   872	            return;
   873	        const bool has_subject = [&data] {
   874	            for (std::size_t pixel = 3; pixel < data.pixels.size(); pixel += 4)
   875	                if (data.pixels[pixel] != 0)
   876	                    return true;
   877	            return false;
   878	        }();
   879	        if (!has_subject)
   880	            return;
   881	        const auto png = GCodeThumbnails::compress_thumbnail(data, GCodeThumbnailsFormat::PNG);
   882	        if (!png || !png->data || png->size == 0 || png->size > kMaxPreviewBytes)
   883	            return;
   884	        write_preview(project, m_store->head_id(),
   885	                      "data:image/png;base64," + base64_encode(std::string(static_cast<const char*>(png->data), png->size)));
   886	    } catch (const std::exception& error) {
   887	        // A preview is derived display data. A failed render or cache write
   888	        // must not prevent opening the committed project.
   889	        BOOST_LOG_TRIVIAL(warning) << "Local project preview unavailable: " << error.what();
   890	    }

