   310	void ProjectAutosave::trim_history()
   311	{
   312	    try {
   313	        std::set<std::string> live_attachments;
   314	        for (const auto& attachment : m_persistence.document().attachments())
   315	            if (!attachment.stored_name.empty())
   316	                live_attachments.insert(attachment.relative_path());
   317	        m_store->prune(kMaxVersions, kMaxBytes, live_attachments);
   318	        m_warning.clear();
   319	    } catch (const std::exception& error) {
   320	        // The current head was already committed. A retention failure leaves
   321	        // extra old data and must not misreport the current project as unsaved.
   322	        m_warning = std::string("Local history cleanup failed: ") + error.what();
   323	        BOOST_LOG_TRIVIAL(warning) << m_warning;
   324	    }
   325	}
   326	
   327	bool ProjectAutosave::settle(bool wait)
   328	{
   329	    if (!m_worker.valid())
   330	        return true;
   331	    if (!wait && m_worker.wait_for(std::chrono::seconds(0)) != std::future_status::ready)
   332	        return false;
   333	    try {
   334	        m_worker.get();
   335	        if (m_worker_kind == WorkerKind::Model) {
   336	            m_committed_head = m_store->head_id();
   337	            m_last_capture_input = std::move(m_inflight_capture_input);
   338	            m_seen_model_input = m_last_capture_input;
   339	            trim_history();
   340	        }
   341	        if (m_worker_kind == WorkerKind::Document)
   342	            m_committed_semantic_revision = m_inflight_semantic_revision;
   343	        m_worker_kind = WorkerKind::None;
   344	        if (m_seen_semantic_revision == m_committed_semantic_revision)
   345	            m_first_semantic_edit.reset();
   346	        m_error.clear();
   347	        // A main-thread edit may have landed while the worker wrote the
   348	        // frozen revision. Probe again before saying the current model is saved.
   349	        m_state = State::Saving;
   350	        m_next_probe = Clock::now();
   351	        return true;
   352	    } catch (const std::exception& error) {
   353	        m_worker_kind = WorkerKind::None;
   354	        m_inflight_capture_input.clear();
   355	        fail(error.what());
   356	    } catch (...) {
   357	        m_worker_kind = WorkerKind::None;
   358	        m_inflight_capture_input.clear();
   359	        fail("project version writer failed");
   360	    }
   361	    return false;
   362	}
   363	
   364	void ProjectAutosave::adopt_project()
   365	{
   366	    m_persistence.resolve_pending_boundary();
   367	    const std::string id = m_persistence.document().project_id();
   368	    if (m_store && m_store->project_id() == id)
   369	        return;
   370	    settle(true);
   371	    m_store.reset();
   372	    if (id.empty())
   373	        throw std::runtime_error("open project has no identity");
   374	    m_store = std::make_unique<ProjectVersionStore>(m_root, id);
   375	    m_last_capture_input.clear();
   376	    m_seen_model_input.clear();
   377	    m_inflight_capture_input.clear();
   378	    m_committed_head = m_store->head_id();
   379	    m_committed_semantic_revision = m_committed_head.empty() ? 0 : m_persistence.document().doc_revision();
   380	    m_seen_semantic_revision = m_persistence.document().doc_revision();
   381	    m_last_semantic_edit = Clock::now();
   382	    m_first_semantic_edit = m_seen_semantic_revision != m_committed_semantic_revision ?
   383	        std::optional<Clock::time_point>(m_last_semantic_edit) : std::nullopt;
   384	    const auto versions = m_store->history();
   385	    m_project_name = versions.empty() ? std::string() : versions.back().project_name;
   386	    m_revision = 0;
   387	    for (const auto& version : versions)
   388	        m_revision = std::max(m_revision, version.revision);
   389	    m_state = State::Saving;
   390	    m_next_probe = Clock::now();
   391	}
