    return url.size() <= (kMaxPreviewBytes * 4 / 3 + 64) &&
           url.rfind("data:image/png;base64,", 0) == 0 ? url : std::string();
}

void write_preview(const std::filesystem::path& project, const std::string& version, const std::string& url)
{
