 193	// Managed checkpoints keep their captured settings; ordinary 3MF exports keep Orca's
 194	// actual preset-difference list. Rewrite only the unpublished backup archive.
 195	void protect_saved_settings(const std::filesystem::path& metadata)
 196	{
 197	    constexpr const char* entry = "Metadata/project_settings.config";
 198	    mz_zip_archive source, target;
 199	    mz_zip_zero_struct(&source);
 200	    mz_zip_zero_struct(&target);
 201	    if (!open_zip_reader(&source, metadata.u8string()))
 202	        throw std::runtime_error("Could not read captured project metadata");
 203	
 204	    bool target_open = false;
 205	    auto rewritten = metadata;
 206	    rewritten += ".rewrite";
 207	    try {
 208	        const int entry_index = mz_zip_reader_locate_file(&source, entry, nullptr, 0);
 209	        if (entry_index < 0)
 210	            throw std::runtime_error("Captured project settings are missing");
 211	        size_t size = 0;
 212	        void* data = mz_zip_reader_extract_file_to_heap(&source, entry, &size, 0);
 213	        if (!data)
 214	            throw std::runtime_error("Could not read captured project settings");
 215	        std::string original(static_cast<const char*>(data), size);
 216	        mz_free(data);
 217	
 218	        auto settings = nlohmann::json::parse(original);
 219	        const auto& colours = settings.at("filament_colour");
 220	        if (!colours.is_array() || colours.empty())
 221	            throw std::runtime_error("Captured project has no filament settings");
 222	        std::vector<std::string> keys;
 223	        for (auto it = settings.begin(); it != settings.end(); ++it)
 224	            if (it.key() != "version" && it.key() != "name" && it.key() != "from" &&
 225	                it.key() != "different_settings_to_system")
 226	                keys.push_back(it.key());
 227	        const std::string protected_keys = escape_strings_cstyle(keys);
 228	        settings["different_settings_to_system"] =
 229	            std::vector<std::string>(colours.size() + 2, protected_keys);
 230	        const std::string replacement = settings.dump(1, '\t') + '\n';
 231	
 232	        if (!open_zip_writer(&target, rewritten.u8string()))
 233	            throw std::runtime_error("Could not rewrite captured project metadata");
 234	        target_open = true;
 235	        for (mz_uint index = 0; index < mz_zip_reader_get_num_files(&source); ++index) {
 236	            const bool added = int(index) == entry_index ?
 237	                mz_zip_writer_add_mem(&target, entry, replacement.data(), replacement.size(), MZ_DEFAULT_COMPRESSION) :
 238	                mz_zip_writer_add_from_zip_reader(&target, &source, index);
 239	            if (!added)
 240	                throw std::runtime_error("Could not copy captured project metadata entry");
 241	        }
 242	        if (!mz_zip_writer_finalize_archive(&target))
 243	            throw std::runtime_error("Could not finalize captured project metadata");
 244	        target_open = false;
 245	        if (!close_zip_writer(&target))
 246	            throw std::runtime_error("Could not close rewritten project metadata");
 247	        if (!close_zip_reader(&source))
 248	            throw std::runtime_error("Could not close captured project metadata");
 249	#ifdef _WIN32
 250	        // This archive is still unpublished staging data; Windows cannot rename over it.
 251	        std::filesystem::remove(metadata);
 252	#endif
 253	        std::filesystem::rename(rewritten, metadata);
 254	    } catch (...) {
 255	        if (target_open) close_zip_writer(&target);
 256	        if (source.m_zip_mode == MZ_ZIP_MODE_READING) close_zip_reader(&source);
 257	        std::error_code ignored;
 258	        std::filesystem::remove(rewritten, ignored);
 259	        throw;
 260	    }
 261	}
